public class A36 {
 public String errors(List<Database.Error> es){
  List<String> xs=new List<String>();
  for(Database.Error e:es) xs.add(String.valueOf(e.getStatusCode())+':'+String.join(e.getFields(),','));
  return String.join(xs,';');
 }
 public String save(Database.SaveResult s){return s.isSuccess()+'|'+(s.getId()!=null)+'|'+errors(s.getErrors());}
 public String up(Database.UpsertResult s){return s.isSuccess()+'|'+s.isCreated()+'|'+(s.getId()!=null)+'|'+errors(s.getErrors());}
 public String del(Database.DeleteResult s){return s.isSuccess()+'|'+(s.getId()!=null)+'|'+errors(s.getErrors());}
 public String undel(Database.UndeleteResult s){return s.isSuccess()+'|'+(s.getId()!=null)+'|'+errors(s.getErrors());}
 public String merged(Database.MergeResult s){return s.isSuccess()+'|'+(s.getId()!=null)+'|'+errors(s.getErrors());}
 public String converted(Database.LeadConvertResult s){return s.isSuccess()+'|'+(s.getLeadId()!=null)+'|'+(s.getAccountId()!=null)+'|'+(s.getContactId()!=null)+'|'+(s.getOpportunityId()!=null)+'|'+errors(s.getErrors());}
}
